using System;
using System.Linq;
using System.Collections.Generic;
using ECOLearning.Models;
using ECOLearning.Services;
using ECOLearning.ViewModels;
using Newtonsoft.Json;
class QuizQuestionReportIntegration {
 static int checks;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS: "+name);checks++;}
 static void Reject(Action a,string name){try{a();}catch(InvalidOperationException){Check(true,name);return;}throw new Exception("Not rejected: "+name);}
 static int Main(){using(var db=new QL_HETHONG_CUNGCAP_KHOAHOCEntities1())using(var tx=db.Database.BeginTransaction())try{
 string id="QR"+Guid.NewGuid().ToString("N").Substring(0,10);
 var teacher=new NguoiDung{hoTen="Report teacher",email=id+"t@test.invalid",matKhau="fixture",vaiTro="GiaoVien",trangThai=true};
 var student=new NguoiDung{hoTen="Report student",email=id+"s@test.invalid",matKhau="fixture",vaiTro="HocVien",trangThai=true};
 db.NguoiDung.Add(teacher);db.NguoiDung.Add(student);db.SaveChanges();
 db.KhoaHoc.Add(new KhoaHoc{maKhoaHoc=id,tenKhoaHoc="Report fixture",maGiaoVien=teacher.maNguoiDung,maDanhMuc=db.DanhMuc.First().maDanhMuc,giaBan=0,trangThai="Đã xuất bản"});db.SaveChanges();
 db.DangKyKhoaHoc.Add(new DangKyKhoaHoc{maDangKy=id,maKhoaHoc=id,maHocVien=student.maNguoiDung,ngayDangKy=DateTime.Now});db.SaveChanges();
 var q=new QuizSnapshotQuestion{Id=123456,Text="Snapshot original",Options=new[]{"A","B","C","D"},CorrectOption=1,Explanation="Private solution"};
 int attempt=db.Database.SqlQuery<int>("INSERT dbo.QuizAttempt(CourseId,StudentId,StartedAt,ExpiresAt,SnapshotJson,Total,PassPercent,Title) VALUES(@p0,@p1,GETUTCDATE(),DATEADD(minute,30,GETUTCDATE()),@p2,1,80,N'Test');SELECT CAST(SCOPE_IDENTITY() AS INT)",id,student.maNguoiDung,JsonConvert.SerializeObject(new[]{q})).Single();
 var service=new QuizQuestionReportService(db);
 Check(service.TeacherNotifications(teacher.maNguoiDung,id).Reports==0&&service.TeacherNotifications(teacher.maNguoiDung,id).Appeals==0,"no badges before incoming requests");
 Check(!service.HasReports(student.maNguoiDung,id),"report history link hidden before first report");
 Check(!new ECOLearning.ViewModels.QuizOverview{Attempts=new System.Collections.Generic.List<ECOLearning.ViewModels.QuizAttempt>()}.CanAppeal,"appeal link hidden without attempts");
 Check(!new ECOLearning.ViewModels.QuizOverview{Attempts=new System.Collections.Generic.List<ECOLearning.ViewModels.QuizAttempt>{new ECOLearning.ViewModels.QuizAttempt()}}.CanAppeal,"active attempt cannot expose appeal link");
 Check(new ECOLearning.ViewModels.QuizOverview{Attempts=new System.Collections.Generic.List<ECOLearning.ViewModels.QuizAttempt>{new ECOLearning.ViewModels.QuizAttempt{SubmittedAt=DateTime.UtcNow}}}.CanAppeal,"submitted attempt exposes appeal link");
 Reject(()=>service.Send(teacher.maNguoiDung,attempt,q.Id,"Đáp án có vẻ sai","test"),"reject other student's attempt");
 Reject(()=>service.Send(student.maNguoiDung,attempt,1,"Đáp án có vẻ sai","test"),"reject question outside snapshot");
 Reject(()=>service.Send(student.maNguoiDung,attempt,q.Id,"Vấn đề khác",""),"other reason requires content");
 service.Send(student.maNguoiDung,attempt,q.Id,"Đáp án có vẻ sai","Please check");
 Check(service.HasReports(student.maNguoiDung,id)&&!service.HasReports(teacher.maNguoiDung,id)&&!service.HasReports(student.maNguoiDung,"missing-course"),"report link scoped to reporting learner and course");
 Check(service.TeacherNotifications(teacher.maNguoiDung,id).Reports==1&&service.TeacherNotifications(teacher.maNguoiDung).Reports==1,"pending report counted for course and all courses");
 Check(service.TeacherNotifications(student.maNguoiDung,id).Reports==0&&service.TeacherNotifications(teacher.maNguoiDung,"missing-course").Reports==0,"notification counts isolated by teacher and course");
 var report=service.List(teacher.maNguoiDung,true,id).Single();Check(report.Question.Text=="Snapshot original","captures server snapshot");
 Reject(()=>service.Send(student.maNguoiDung,attempt,q.Id,"Đáp án có vẻ sai","duplicate"),"reject duplicate report atomically");
 Reject(()=>service.Respond(student.maNguoiDung,report.Id,"Answered","Wrong teacher"),"teacher ownership enforced");
 Reject(()=>service.Respond(teacher.maNguoiDung,report.Id,"Answered",""),"resolved report requires response");
 service.Respond(teacher.maNguoiDung,report.Id,"Processing","Checking");Check(service.TeacherNotifications(teacher.maNguoiDung,id).Reports==1,"processing report stays in reminder count");
 service.Respond(teacher.maNguoiDung,report.Id,"Answered","Explanation");Check(service.TeacherNotifications(teacher.maNguoiDung,id).Reports==0,"answered report clears reminder count");
 var mine=service.List(student.maNguoiDung,false,id).Single();Check(mine.Response==null && mine.Question.CorrectOption==-1 && mine.Question.Explanation==null,"hide response and answer key during attempt");
 Check(service.List(teacher.maNguoiDung,false,id).Count==0,"isolate students' reports");
 var visibility=new QuizVisibilityService(db);
 Check(visibility.CountsForTeacher(teacher.maNguoiDung,id,student.maNguoiDung).Count==0,"no attempt warning before recorded visibility event");string eventKey=Guid.NewGuid().ToString("N");
 Reject(()=>visibility.Record(teacher.maNguoiDung,attempt,eventKey,false),"visibility checks attempt ownership");
 visibility.Record(student.maNguoiDung,attempt,eventKey,false);
 visibility.Record(student.maNguoiDung,attempt,eventKey,false);
 var events=visibility.ForTeacher(teacher.maNguoiDung,attempt);Check(events.Count==1 && !events[0].ReturnedAt.HasValue,"visibility duplicate leave is idempotent");
 Reject(()=>visibility.ForTeacher(student.maNguoiDung,attempt),"visibility teacher ownership enforced");
 db.Database.ExecuteSqlCommand("UPDATE dbo.QuizVisibility SET LeftAt=DATEADD(second,-30,GETUTCDATE()) WHERE AttemptId=@p0",attempt);
 visibility.Record(student.maNguoiDung,attempt,eventKey,true);
 var firstReturn=visibility.ForTeacher(teacher.maNguoiDung,attempt).Single();
 visibility.Record(student.maNguoiDung,attempt,eventKey,true);
 Check(visibility.ForTeacher(teacher.maNguoiDung,attempt).Single().ReturnedAt==firstReturn.ReturnedAt,"visibility duplicate return cannot inflate time");
 Check(firstReturn.Seconds>=29 && firstReturn.Seconds<=32,"visibility duration uses server clock");
 string openKey=Guid.NewGuid().ToString("N");visibility.Record(student.maNguoiDung,attempt,openKey,false);
 db.Database.ExecuteSqlCommand("UPDATE dbo.QuizAttempt SET SubmittedAt=GETUTCDATE() WHERE Id=@p0",attempt);
 visibility.Record(student.maNguoiDung,attempt,Guid.NewGuid().ToString("N"),false);
 Check(visibility.ForTeacher(teacher.maNguoiDung,attempt).Count==2,"no new leave after submission");
 Check(visibility.CountsForTeacher(teacher.maNguoiDung,id,student.maNguoiDung)[attempt]==2,"history marker uses actual event count for each attempt");
 Check(visibility.CountsForTeacher(student.maNguoiDung,id,student.maNguoiDung).Count==0&&visibility.CountsForTeacher(teacher.maNguoiDung,id,teacher.maNguoiDung).Count==0&&visibility.CountsForTeacher(teacher.maNguoiDung,"missing-course",student.maNguoiDung).Count==0,"history event counts isolated by teacher learner and course");
 visibility.Record(student.maNguoiDung,attempt,openKey,true);
 Check(visibility.ForTeacher(teacher.maNguoiDung,attempt).All(v=>v.Seconds>=0),"late return is capped at submission");
 mine=service.List(student.maNguoiDung,false,id).Single();Check(mine.Response=="Explanation" && mine.Status=="Answered","show response after submission");
 db.Database.ExecuteSqlCommand("INSERT dbo.QuizAppeal(AttemptId,StudentId,Content) VALUES(@p0,@p1,N'Notification fixture')",attempt,student.maNguoiDung);
 Check(service.TeacherNotifications(teacher.maNguoiDung,id).Appeals==1&&service.TeacherNotifications(student.maNguoiDung,id).Appeals==0,"pending appeal count belongs only to course teacher");
 db.Database.ExecuteSqlCommand("UPDATE dbo.QuizAppeal SET Status='Processing' WHERE AttemptId=@p0",attempt);Check(service.TeacherNotifications(teacher.maNguoiDung,id).Appeals==1,"processing appeal keeps reminder");
 db.Database.ExecuteSqlCommand("UPDATE dbo.QuizAppeal SET Status='Answered' WHERE AttemptId=@p0",attempt);Check(service.TeacherNotifications(teacher.maNguoiDung,id).Appeals==0,"answered appeal clears reminder");
 var a=new QuizService(db).Attempt(attempt);Check(a.Score==null && a.AnswersJson==null && a.Total==1,"reports do not alter scores or answers");
 Check(visibility.UnreadCount(teacher.maNguoiDung)==0,"fewer than three leaves do not create global reminder");
 var oldWatermark=visibility.ForTeacher(teacher.maNguoiDung,attempt).Max(v=>v.Id);
 db.Database.ExecuteSqlCommand("INSERT dbo.QuizVisibility(AttemptId,EventKey,LeftAt,ReturnedAt) VALUES(@p0,@p1,DATEADD(second,-20,GETUTCDATE()),DATEADD(second,-10,GETUTCDATE()))",attempt,Guid.NewGuid().ToString("N"));
 Check(visibility.UnreadCount(teacher.maNguoiDung)==1,"three leaves create one unread attempt reminder");
 var alert=visibility.Alerts(teacher.maNguoiDung).Single();Check(alert.AttemptId==attempt&&alert.StudentId==student.maNguoiDung&&alert.Count==3&&alert.IsUnread&&alert.Seconds>=30,"review queue includes learner course actual counts and duration");
 Check(visibility.UnreadCount(student.maNguoiDung)==0&&visibility.Alerts(student.maNguoiDung).Count==0&&visibility.Alerts(teacher.maNguoiDung,"other-course").Count==0,"global reminders and queue are isolated by course teacher");
 Check(visibility.Alerts(teacher.maNguoiDung,id,"Report student").Count==1&&visibility.Alerts(teacher.maNguoiDung,id,"Not found").Count==0,"review queue search filters learners");
 Reject(()=>visibility.MarkReviewed(student.maNguoiDung,attempt,alert.LastEventId),"another user cannot acknowledge teacher reminder");
 Reject(()=>visibility.MarkReviewed(teacher.maNguoiDung,attempt,int.MaxValue),"cannot acknowledge nonexistent or future event watermark");
 visibility.MarkReviewed(teacher.maNguoiDung,attempt,oldWatermark);Check(visibility.UnreadCount(teacher.maNguoiDung)==1,"new events after the loaded watermark remain unread");
 visibility.MarkReviewed(teacher.maNguoiDung,attempt,alert.LastEventId);Check(visibility.UnreadCount(teacher.maNguoiDung)==0&&visibility.Alerts(teacher.maNguoiDung).Count==0,"opening detail clears only the viewed attempt reminder");
 Check(visibility.Alerts(teacher.maNguoiDung,id,null,true).Count==1&&!visibility.Alerts(teacher.maNguoiDung,id,null,true).Single().IsUnread&&visibility.ForTeacher(teacher.maNguoiDung,attempt).Count==3,"seen logs remain available without deleting history");
 visibility.MarkReviewed(teacher.maNguoiDung,attempt,oldWatermark);Check(visibility.UnreadCount(teacher.maNguoiDung)==0,"stale acknowledgement cannot move watermark backwards");
 db.Database.ExecuteSqlCommand("INSERT dbo.QuizVisibility(AttemptId,EventKey,LeftAt) VALUES(@p0,@p1,GETUTCDATE())",attempt,Guid.NewGuid().ToString("N"));Check(visibility.UnreadCount(teacher.maNguoiDung)==1,"another recorded event reactivates previously viewed reminder");
 Console.WriteLine(checks+" checks passed; fixture rolled back.");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{tx.Rollback();}}
}
